<?php
namespace CloudHost247\Ovh\Services;use WHMCS\Database\Capsule;use InvalidArgumentException;
final class MappingRepository
{function save(array$i){$pid=(int)$i['whmcs_product_id'];$eid=(int)$i['endpoint_id'];$family=(string)$i['family'];$plan=trim((string)$i['plan_code']);$sub=strtoupper(trim((string)$i['subsidiary']));if(!$pid||!Capsule::table('tblproducts')->where('id',$pid)->exists())throw new InvalidArgumentException('WHMCS product does not exist.');if(!$eid||!Capsule::table('mod_cloudhost247_ovh_endpoints')->where('id',$eid)->exists())throw new InvalidArgumentException('Endpoint does not exist.');if(!in_array($family,array('eco','vps','dedicated'),true)||!preg_match('/^[A-Za-z0-9._-]{2,191}$/',$plan)||!preg_match('/^[A-Z]{2,8}$/',$sub))throw new InvalidArgumentException('Invalid OVH mapping.');$config=json_decode($i['configuration_json']??'{}',true);if(!is_array($config))throw new InvalidArgumentException('Configuration must be JSON object.');Capsule::table('mod_cloudhost247_ovh_product_mappings')->updateOrInsert(array('whmcs_product_id'=>$pid),array('endpoint_id'=>$eid,'family'=>$family,'plan_code'=>$plan,'subsidiary'=>$sub,'configuration_json'=>json_encode($config),'active'=>!empty($i['active']), 'margin_percent'=>(float)($i['margin_percent']??0),'updated_at'=>date('Y-m-d H:i:s')));}
 function forProduct($id){return Capsule::table('mod_cloudhost247_ovh_product_mappings')->where('whmcs_product_id',(int)$id)->where('active',1)->first();}}
